var e={COMMON:{CONFORMANCE_LEVEL:"Niveau"},PRINCIPLE:{1:{TITLE:"Waarneembaar",DESCRIPTION:"Informatie en componenten van de gebruikersinterface moeten toonbaar zijn aan gebruikers op voor hen waarneembare wijze."},2:{TITLE:"Bedienbaar",DESCRIPTION:"Componenten van de gebruikersinterface en navigatie moeten bedienbaar zijn."},3:{TITLE:"Begrijpelijk",DESCRIPTION:"Informatie en de bediening van de gebruikersinterface moeten begrijpelijk zijn."},4:{TITLE:"Robuust",DESCRIPTION:"Content moet voldoende robuust zijn om betrouwbaar geïnterpreteerd te kunnen worden door een breed scala van user agents, met inbegrip van hulptechnologieën."}},GUIDELINE:{1.1:{TITLE:"Tekstalternatieven",DESCRIPTION:"Lever tekstalternatieven voor alle niet-tekstuele content, zodat die veranderd kan worden in andere vormen die mensen nodig hebben, zoals grote letters, braille, spraak, symbolen of eenvoudigere taal."},1.2:{TITLE:"Op tijd gebaseerde media",DESCRIPTION:"Lever alternatieven voor op tijd gebaseerde media."},1.3:{TITLE:"Aanpasbaar",DESCRIPTION:"Creëer content die op verschillende manieren gepresenteerd kan worden (bijvoorbeeld eenvoudiger lay-out) zonder verlies van informatie of structuur."},1.4:{TITLE:"Onderscheidbaar",DESCRIPTION:"Maak het voor gebruikers gemakkelijker om content te horen en te zien, waaronder scheiding van voorgrond en achtergrond."},2.1:{TITLE:"Toetsenbordtoegankelijk",DESCRIPTION:"Maak alle functionaliteit beschikbaar vanaf een toetsenbord."},2.2:{TITLE:"Genoeg tijd",DESCRIPTION:"Geef gebruikers genoeg tijd om content te lezen en te gebruiken."},2.3:{TITLE:"Toevallen en fysieke reacties",DESCRIPTION:"Ontwerp content niet op een manier waarvan bekend is dat die toevallen of fysieke reacties veroorzaakt."},2.4:{TITLE:"Navigeerbaar",DESCRIPTION:"Lever manieren om gebruikers te helpen navigeren, content te vinden en te bepalen waar ze zijn."},2.5:{TITLE:"Input Modaliteiten",DESCRIPTION:"Maak het eenvoudiger voor gebruikers om de functionaliteit te bedienen met andere vormen van invoer dan alleen het toetsenbord."},3.1:{TITLE:"Leesbaar",DESCRIPTION:"Maak tekstcontent leesbaar en begrijpelijk."},3.2:{TITLE:"Voorspelbaar",DESCRIPTION:"Maak het uiterlijk en de bediening van webpagina's voorspelbaar."},3.3:{TITLE:"Assistentie bij invoer",DESCRIPTION:"Help gebruikers om fouten te vermijden en ze te verbeteren."},4.1:{TITLE:"Compatibel",DESCRIPTION:"Maximaliseer compatibiliteit met huidige en toekomstige user agents, met inbegrip van hulptechnologieën."}},SUCCESS_CRITERION:{"1.1.1":{TITLE:"Niet-tekstuele content",DESCRIPTION:"Alle niet-tekstuele content die aan de gebruiker wordt gepresenteerd, heeft een tekstalternatief dat een gelijkwaardig doel dient, behalve voor de hierna vermelde situaties.",DETAILS:{1:{DESCRIPTION:"Als niet-tekstuele content een bedieningselement is of gebruikersinvoer accepteert, dan heeft deze een naam die het doel ervan beschrijft. (We verwijzen naar succescriterium 4.1.2 voor aanvullende eisen ten aanzien van bedieningselementen en content die gebruikersinvoer accepteren.)",TITLE:"Bedieningselementen, invoer"},2:{DESCRIPTION:"Als niet-tekstuele content op tijd gebaseerde media is, dan leveren tekstalternatieven ten minste een beschrijving van de niet-tekstuele content. (We verwijzen naar Richtlijn 1.2 voor aanvullende eisen ten aanzien van media.)",TITLE:"Op tijd gebaseerde media"},3:{DESCRIPTION:"Als niet-tekstuele content een test of oefening is die, als ze door middel van tekst gepresenteerd wordt onjuist zou zijn, dan leveren tekstalternatieven ten minste een beschrijving van de niet-tekstuele content.",TITLE:"Test"},4:{DESCRIPTION:"Als niet-tekstuele content primair is bedoeld om een specifieke zintuiglijke ervaring te creëren, dan leveren tekstalternatieven ten minste een beschrijving van de niet-tekstuele content.",TITLE:"Zintuiglijk"},5:{DESCRIPTION:"Als het doel van niet-tekstuele content is om te bevestigen dat content wordt gebruikt door een persoon in plaats van een computer, dan worden tekstalternatieven geleverd die het doel van de niet-tekstuele content identificeren en beschrijven. En er worden alternatieve vormen van CAPTCHA aangeboden gebruikmakend van uitvoermodes voor verschillende soorten van zintuiglijke perceptie om tegemoet te komen aan verschillende functiebeperkingen.",TITLE:"CAPTCHA"},6:{DESCRIPTION:"Als niet-tekstuele content puur decoratief is, slechts voor visuele opmaak wordt gebruikt, of niet aan gebruikers wordt gerepresenteerd, dan wordt het op zo'n manier geïmplementeerd dat het genegeerd kan worden door hulptechnologie.",TITLE:"Decoratie, opmaak, onzichtbaar"}}},"1.2.1":{TITLE:"Louter-geluid en louter-videobeeld (vooraf opgenomen)",DESCRIPTION:"Voor media met vooraf opgenomen louter-geluid en vooraf opgenomen louter-videobeeld is het volgende waar, behalve als de audio of video een media-alternatief voor tekst is en duidelijk als zodanig is gelabeld:",DETAILS:{1:{DESCRIPTION:"Er wordt een alternatief geleverd voor op tijd gebaseerde media dat equivalente informatie geeft voor vooraf opgenomen louter-geluid content.",TITLE:"Vooraf opgenomen louter-geluid"},2:{DESCRIPTION:"Er wordt een alternatief geleverd voor op tijd gebaseerde media of een geluidsspoor dat equivalente informatie geeft voor vooraf opgenomen louter-videobeeld content.",TITLE:"Vooraf opgenomen louter-videobeeld"}}},"1.2.2":{TITLE:"Ondertitels voor doven en slechthorenden (vooraf opgenomen)",DESCRIPTION:"Er worden ondertitels voor doven en slechthorenden geleverd voor alle vooraf opgenomen audiocontent in gesynchroniseerde media, behalve als het mediabestand een media-alternatief voor tekst is en duidelijk als zodanig is gelabeld.",DETAILS:{}},"1.2.3":{TITLE:"Audiodescriptie of media-alternatief (vooraf opgenomen)",DESCRIPTION:"Er wordt een alternatief geleverd voor op tijd gebaseerde media of audiodescriptie van de vooraf opgenomen videocontent geleverd voor gesynchroniseerde media, behalve als het mediabestand een media-alternatief voor tekst is en duidelijk als zodanig is gelabeld.",DETAILS:{}},"1.2.4":{TITLE:"Ondertitels voor doven en slechthorenden (live)",DESCRIPTION:"Er worden ondertitels voor doven en slechthorenden geleverd voor alle live audiocontent in gesynchroniseerde media.",DETAILS:{}},"1.2.5":{TITLE:"Audiodescriptie (vooraf opgenomen)",DESCRIPTION:"Er wordt een audiodescriptie geleverd voor alle vooraf opgenomen videocontent in gesynchroniseerde media.",DETAILS:{}},"1.2.6":{TITLE:"Gebarentaal (vooraf opgenomen)",DESCRIPTION:"Er wordt een gebarentaalvertolking geleverd voor alle vooraf opgenomen audiocontent in gesynchroniseerde media.",DETAILS:{}},"1.2.7":{TITLE:"Verlengde audiodescriptie (vooraf opgenomen)",DESCRIPTION:"Waar pauzes in voorgrondgeluid onvoldoende zijn om audiodescripties toe te passen om de boodschap van de video over te brengen, wordt een verlengde audiodescriptie geleverd voor alle vooraf opgenomen videocontent in gesynchroniseerde media.",DETAILS:{}},"1.2.8":{TITLE:"Media-alternatief (vooraf opgenomen)",DESCRIPTION:"Er wordt een alternatief geleverd voor op tijd gebaseerde media voor alle vooraf opgenomen gesynchroniseerde media en voor alle vooraf opgenomen louter-videobeeld media.",DETAILS:{}},"1.2.9":{TITLE:"Louter-geluid (live)",DESCRIPTION:"Er wordt een alternatief geleverd voor op tijd gebaseerde media dat equivalente informatie presenteert voor live louter-geluid content.",DETAILS:{}},"1.3.1":{TITLE:"Info en relaties",DESCRIPTION:"Informatie, structuur en relaties overgebracht door presentatie kunnen door software bepaald worden of zijn beschikbaar in tekst.",DETAILS:{}},"1.3.2":{TITLE:"Betekenisvolle volgorde",DESCRIPTION:"Als de volgorde waarin content wordt gepresenteerd van invloed is op zijn betekenis, kan een correcte leesvolgorde door software bepaald worden.",DETAILS:{}},"1.3.3":{TITLE:"Zintuiglijke eigenschappen",DESCRIPTION:"Instructies die geleverd worden om content te begrijpen en te bedienen zijn niet alleen afhankelijk van zintuiglijke eigenschappen van componenten zoals vorm, kleur, omvang, visuele locatie, oriëntatie of geluid.",DETAILS:{}},"1.3.4":{TITLE:"Weergavestand",DESCRIPTION:"De content beperkt de weergave en bediening niet tot een enkele presentatie-oriëntatie, zoals staand of liggend, tenzij een specifieke presentatie-oriëntatie essentieel is.",DETAILS:{}},"1.3.5":{TITLE:"Identificeer het doel van de input",DESCRIPTION:"Het doel van elk invoerveld waarmee informatie van de gebruiker wordt verzameld, kan door software bepaald worden wanneer:",DETAILS:{1:{DESCRIPTION:"Het invoerveld een doel dient dat is geïdentificeerd in de paragraaf Inputdoelen voor Componenten van de Gebruikersinterface; en"},2:{DESCRIPTION:"De content wordt geïmplementeerd met behulp van technologieën die ondersteuning bieden bij het identificeren van de verwachte betekenis van formulier-invoergegevens."}}},"1.3.6":{TITLE:"Identificeer het doel",DESCRIPTION:"In content die is geïmplementeerd met opmaaktalen, kan het doel van de componenten van de gebruikersinterface, pictogrammen en regio's door software bepaald worden.",DETAILS:{}},"1.4.1":{TITLE:"Gebruik van kleur",DESCRIPTION:"Kleur wordt niet als het enige visuele middel gebruikt om informatie over te brengen, een actie aan te geven, tot een reactie op te roepen of een visueel element te onderscheiden.",DETAILS:{}},"1.4.2":{TITLE:"Geluidsbediening",DESCRIPTION:"Als een geluidsweergave op een webpagina automatisch meer dan 3 seconden speelt, is er of een mechanisme beschikbaar om de geluidsweergave te pauzeren of te stoppen, of er is een mechanisme beschikbaar om het geluidsvolume onafhankelijk van het overall systeemvolume te regelen.",DETAILS:{}},"1.4.3":{TITLE:"Contrast (minimum)",DESCRIPTION:"De visuele weergave van tekst en afbeeldingen van tekst heeft een contrastverhouding van ten minste 4,5:1, behalve in de volgende gevallen:",DETAILS:{1:{DESCRIPTION:"Grote tekst en afbeeldingen van grote tekst hebben een contrastverhouding van ten minste 3:1;",TITLE:"Grote tekst"},2:{DESCRIPTION:"Tekst of afbeeldingen van tekst die deel zijn van een inactieve component van de gebruikersinterface, die puur decoratief zijn, die voor niemand zichtbaar zijn, of die onderdeel zijn van een afbeelding die significant andere visuele content bevat, hebben geen contrasteis.",TITLE:"Incidenteel"},3:{DESCRIPTION:"Tekst die onderdeel is van een logo of merknaam heeft geen contrasteis.",TITLE:"Woordmerken"}}},"1.4.4":{TITLE:"Herschalen van tekst",DESCRIPTION:"Behalve voor ondertitels voor doven en slechthorenden en afbeeldingen van tekst, kan tekst zonder hulptechnologie tot 200% geschaald worden zonder verlies van content of functionaliteit.",DETAILS:{}},"1.4.5":{TITLE:"Afbeeldingen van tekst",DESCRIPTION:"Als de gebruikte technologieën de visuele weergave tot stand kunnen brengen, wordt tekst gebruikt in plaats van afbeeldingen van tekst om informatie over te brengen, behalve in de volgende gevallen:",DETAILS:{1:{DESCRIPTION:"De afbeelding van tekst kan visueel aangepast worden aan de eisen van de gebruiker;",TITLE:"Aanpasbaar"},2:{DESCRIPTION:"Een specifieke weergave van tekst is essentieel voor de informatie die wordt overgebracht.",TITLE:"Essentieel"}}},"1.4.6":{TITLE:"Contrast (versterkt)",DESCRIPTION:"De visuele weergave van tekst en afbeeldingen van tekst heeft een contrastverhouding van ten minste 7:1, behalve in de volgende gevallen:",DETAILS:{1:{DESCRIPTION:"Grote tekst en afbeeldingen van grote tekst hebben een contrastverhouding van ten minste 4,5:1;",TITLE:"Grote tekst"},2:{DESCRIPTION:"Tekst of afbeeldingen van tekst die onderdeel zijn van een inactieve componenten van de gebruikersinterface, die puur decoratief zijn, die voor niemand zichtbaar zijn, of die onderdeel zijn van een afbeelding die significant andere visuele content bevat, hebben geen contrasteis.",TITLE:"Incidenteel"},3:{DESCRIPTION:"Tekst die onderdeel is van een logo of merknaam heeft geen contrasteis.",TITLE:"Woordmerken"}}},"1.4.7":{TITLE:"Weinig of geen achtergrondgeluid",DESCRIPTION:"Voor vooraf opgenomen louter-geluidcontent die (1) voornamelijk spraak op de voorgrond bevat, (2) geen geluids-CAPTCHA of audiologo is, en (3) geen vocalisatie is die primair bedoeld is als muzikale expressie zoals zingen of rappen, is ten minste één van de volgende zaken waar:",DETAILS:{1:{DESCRIPTION:"De geluidsopname bevat geen achtergrondgeluiden.",TITLE:"Geen achtergrond:"},2:{DESCRIPTION:"De achtergrondgeluiden kunnen uitgezet worden.",TITLE:"Uitzetten"},3:{DESCRIPTION:'De achtergrondgeluiden zijn ten minste 20 decibel lager dan spraak content die op de voorgrond klinkt, met uitzondering van incidentele geluiden die slechts één of twee seconden duren. Noot Uit de definitie van "decibel" volgt dat achtergrondgeluid dat aan deze eis voldoet ongeveer vier keer zachter klinkt dan de spraak content op de voorgrond.',TITLE:"20 dB"}}},"1.4.8":{TITLE:"Visuele weergave",DESCRIPTION:"Voor de visuele weergave van tekstblokken is een mechanisme beschikbaar om het volgende te realiseren:",DETAILS:{1:{DESCRIPTION:"Voor- en achtergrondkleuren kunnen door de gebruiker worden gekozen."},2:{DESCRIPTION:"De breedte is niet meer dan 80 karakters of tekens (40 in het geval van CJK)."},3:{DESCRIPTION:"Tekst is niet uitgevuld (uitgelijnd naar linker- en rechterkantlijnen)."},4:{DESCRIPTION:"Regelafstand is ten minste 1,5 spatie binnen alinea's en alinea-afstand is ten minste 1,5 keer zo groot als de regelafstand."},5:{DESCRIPTION:"Tekst kan zonder hulptechnologie herschaald worden tot 200% op een zodanige manier dat de gebruiker niet horizontaal hoeft te scrollen om een regel tekst te lezen op een venster even groot als het volle beeld."}}},"1.4.9":{TITLE:"Afbeeldingen van tekst (geen uitzondering)",DESCRIPTION:"Afbeeldingen van tekst worden alleen puur decoratief gebruikt, of daar waar een specifieke weergave van tekst essentieel is voor de informatie die wordt overgebracht.",DETAILS:{}},"1.4.10":{TITLE:"Reflow",DESCRIPTION:"Content kan zonder verlies van informatie of functionaliteit en zonder te moeten scrollen in twee dimensies, worden weergegeven voor:",DETAILS:{1:{DESCRIPTION:"Verticaal scrollbare content met een breedte gelijkwaardig aan 320 CSS-pixels;"},2:{DESCRIPTION:"Horizontaal scrollbare content met een hoogte gelijkwaardig aan 256 CSS-pixels;"}}},"1.4.11":{TITLE:"Contrast van niet-tekstuele content",DESCRIPTION:"De visuele weergave van het volgende heeft een contrastverhouding van ten minste 3:1 ten opzichte van aangrenzende kleuren:",DETAILS:{1:{DESCRIPTION:"Visuele informatie die vereist is om componenten van de gebruikersinterface en statussen te identificeren, met uitzondering van inactieve componenten of componenten waarvan de weergave van de component wordt bepaald door de user agent en niet wordt aangepast door de auteur;",TITLE:"Componenten van de gebruikersinterface"},2:{DESCRIPTION:"Delen van afbeeldingen die vereist zijn om de content te begrijpen, behalve wanneer een specifieke weergave van afbeeldingen essentieel is voor de informatie die wordt overgebracht.",TITLE:"Grafische objecten"}}},"1.4.12":{TITLE:"Tekstafstand",DESCRIPTION:"Bij content die wordt geïmplementeerd met opmaaktalen die de volgende stijleigenschappen voor tekst ondersteunen, is er geen sprake van verlies van content of functionaliteit door het instellen van alle volgende, en door het niet wijzigen van andere stijleigenschappen:",DETAILS:{1:{DESCRIPTION:"Regelhoogte (regelafstand) naar ten minste 1,5 keer de lettergrootte;"},2:{DESCRIPTION:"Afstand tussen alinea's naar ten minste 2 keer de lettergrootte;"},3:{DESCRIPTION:"Letterafstand (spatiëren van letters) naar ten minste 0,12 keer de lettergrootte;"},4:{DESCRIPTION:"Spatiëren van woorden naar ten minste 0,16 keer de lettergrootte."}}},"1.4.13":{TITLE:"Content bij hover of focus",DESCRIPTION:"Wanneer aanvullende content zichtbaar wordt en daarna weer verborgen, door het gebruik van hover met de aanwijzer of focus met het toetsenbord, gelden de volgende zaken:",DETAILS:{1:{DESCRIPTION:"Er is een mechanisme beschikbaar waarmee de aanvullende content kan worden gesloten zonder de aanwijzer hover of de toetsenbordfocus te verplaatsen, tenzij de aanvullende content een invoerfout communiceert of andere content niet verbergt of vervangt;",TITLE:"Sluiten"},2:{DESCRIPTION:"Wanneer een aanwijzer hover aanvullende content kan activeren, dan kan de aanwijzer over de aanvullende content worden bewogen zonder dat deze verdwijnt;",TITLE:"Aanwijsbaar"},3:{DESCRIPTION:"De aanvullende content blijft zichtbaar totdat de oorzaak voor de hover of focus is verwijderd, de gebruiker de content sluit of de informatie niet langer geldig is.",TITLE:"Aanhouden"}}},"2.1.1":{TITLE:"Toetsenbord",DESCRIPTION:"Alle functionaliteit van de content is bedienbaar via een toetsenbordinterface zonder dat afzonderlijke toetsaanslagen aan tijd gebonden zijn, behalve als de onderliggende functie een invoer vereist die afhangt van het pad dat de gebruiker aflegt en niet alleen van de eindpunten.",DETAILS:{}},"2.1.2":{TITLE:"Geen toetsenbordval",DESCRIPTION:"Als de toetsenbordfocus met de toetsenbordinterface verplaatst kan worden naar een component van de pagina, dan kan de focus ook met alleen de toetsenbordinterface weer van dat component weg worden bewogen. En, als er meer nodig is dan de standaard pijl- of tabtoetsen of andere standaard methoden om de focus te verplaatsen, dan wordt de gebruiker geïnformeerd over de manier waarop de focus kan worden verplaatst.",DETAILS:{}},"2.1.3":{TITLE:"Toetsenbord (geen uitzondering)",DESCRIPTION:"Alle functionaliteit van de content is bedienbaar via een toetsenbordinterface zonder specifieke timing te vereisen voor de individuele toetsaanslagen",DETAILS:{}},"2.1.4":{TITLE:"Enkel teken sneltoetsen",DESCRIPTION:"Wanneer een sneltoets in content wordt geïmplementeerd door alleen letters (inclusief hoofdletters en kleine letters), leestekens, cijfers of symbolen te gebruiken, geldt ten minste één van de volgende zaken:",DETAILS:{1:{DESCRIPTION:"Er is een mechanisme beschikbaar waarmee de sneltoets kan worden uitgezet;",TITLE:"Uitzetten"},2:{DESCRIPTION:"Er is een mechanisme beschikbaar om de sneltoets opnieuw toe te wijzen aan één of meerdere niet-afdrukbare tekens (bijv. Ctrl, Alt, enz.);",TITLE:"Opnieuw toewijzen"},3:{DESCRIPTION:"De sneltoets voor een component van de gebruikersinterface is alleen actief wanneer de betreffende component de focus heeft.",TITLE:"Alleen actief bij focus"}}},"2.2.1":{TITLE:"Timing aanpasbaar",DESCRIPTION:"Voor elke tijdslimiet die door de content wordt ingesteld, geldt ten minste één van de volgende zaken:",DETAILS:{1:{DESCRIPTION:"De gebruiker kan de tijdslimiet uitzetten voordat die wordt bereikt; of",TITLE:"Uitzetten"},2:{DESCRIPTION:"De gebruiker mag de tijdslimiet aanpassen voordat deze is verstreken over een bereik van ten minste tien keer de standaardinstelling; of",TITLE:"Aanpassen"},3:{DESCRIPTION:'De gebruiker wordt gewaarschuwd voor de tijd afloopt en krijgt ten minste 20 seconden om de tijdslimiet met een eenvoudige handeling te verlengen (bijvoorbeeld, "druk op de spatiebalk"), en de gebruiker mag de tijdslimiet ten minste tien keer verlengen; of',TITLE:"Verlengen"},4:{DESCRIPTION:"De tijdslimiet is onderdeel van een realtime gebeurtenis (een veiling bijvoorbeeld) en er is geen alternatief voor de tijdslimiet mogelijk; of",TITLE:"Real-time uitzondering"},5:{DESCRIPTION:"De tijdslimiet is essentieel en verlenging zou de activiteit ongeldig maken; of",TITLE:"Essentiële uitzondering"},6:{DESCRIPTION:"De tijdslimiet is langer dan 20 uur.",TITLE:"20 uur uitzondering"}}},"2.2.2":{TITLE:"Pauzeren, stoppen, verbergen",DESCRIPTION:"Voor alle bewegende, knipperende, scrollende of automatisch actualiserende informatie gelden alle volgende zaken:",DETAILS:{1:{DESCRIPTION:"Voor bewegende, knipperende of scrollende informatie die (1) automatisch start, (2) langer dan vijf seconden duurt, en (3) parallel met andere content wordt getoond, is er een mechanisme voor de gebruiker om dit te pauzeren, te stoppen of te verbergen, tenzij de beweging, knippering of scrolling, onderdeel is van een activiteit waar ze essentieel is en",TITLE:"Bewegen, knipperen, scrollen"},2:{DESCRIPTION:"Voor elke soort automatisch actualiserende informatie die (1) automatisch start en (2) parallel met andere content wordt gepresenteerd, is er een mechanisme voor de gebruiker om dit te pauzeren, te stoppen of te verbergen of de frequentie van de actualisering in te stellen, tenzij de automatische actualisering onderdeel is van een activiteit waar ze essentieel is.",TITLE:"Automatisch actualiserend"}}},"2.2.3":{TITLE:"Geen timing",DESCRIPTION:"Timing is geen essentieel onderdeel van de gebeurtenis of activiteit die door de content wordt weergegeven, behalve voor niet-interactieve gesynchroniseerde media en real-time gebeurtenissen.",DETAILS:{}},"2.2.4":{TITLE:"Onderbrekingen",DESCRIPTION:"Onderbrekingen kunnen uitgesteld of uitgezet worden door de gebruiker, behalve onderbrekingen die met een noodsituatie samenhangen.",DETAILS:{}},"2.2.5":{TITLE:"Herauthentisering",DESCRIPTION:"Als een geauthentiseerde sessie verloopt, kan de gebruiker na herauthentisering de activiteit zonder gegevensverlies voortzetten.",DETAILS:{}},"2.2.6":{TITLE:"Time-outs",DESCRIPTION:"Gebruikers worden gewaarschuwd voor een periode van gebruikersinactiviteit die kan leiden tot verlies van gegevens, tenzij de gegevens gedurende meer dan 20 uur worden bewaard wanneer de gebruiker geen actie onderneemt.",DETAILS:{}},"2.3.1":{TITLE:"Drie flitsen of beneden drempelwaarde",DESCRIPTION:"Webpagina's bevatten niets wat meer dan drie keer flitst in enige periode van één seconde of de flits is beneden de algemene flits- en rodeflitsdrempelwaarden.",DETAILS:{}},"2.3.2":{TITLE:"Drie flitsen",DESCRIPTION:"Webpagina's bevatten niets wat meer dan drie keer flitst in enige periode van één seconde.",DETAILS:{}},"2.3.3":{TITLE:"Animatie uit interacties",DESCRIPTION:"Bewegingsanimatie die door interactie wordt geactiveerd, kan worden uitgeschakeld, behalve als de animatie essentieel is voor de functionaliteit of voor de informatie die wordt overgebracht.",DETAILS:{}},"2.4.1":{TITLE:"Blokken omzeilen",DESCRIPTION:"Er is een mechanisme beschikbaar om blokken content die op meerdere webpagina's worden herhaald te omzeilen.",DETAILS:{}},"2.4.2":{TITLE:"Paginatitel",DESCRIPTION:"Webpagina's hebben titels die het onderwerp of doel beschrijven.",DETAILS:{}},"2.4.3":{TITLE:"Focus volgorde",DESCRIPTION:"Als in webpagina's sequentieel genavigeerd kan worden en de navigatiesequenties hebben invloed op de betekenis of het gebruik, dan krijgen focusbare componenten de focus in de juiste volgorde waardoor betekenis en bedienbaarheid behouden blijft.",DETAILS:{}},"2.4.4":{TITLE:"Linkdoel (in context)",DESCRIPTION:"Het linkdoel kan bepaald worden uit enkel de linktekst of uit de linktekst samen met zijn door software bepaalde linkcontext, behalve daar waar het doel van de link een dubbelzinnige betekenis kan hebben voor gebruikers in het algemeen.",DETAILS:{}},"2.4.5":{TITLE:"Meerdere manieren",DESCRIPTION:"Er is meer dan één manier beschikbaar om een webpagina binnen een verzameling webpagina's te vinden, behalve wanneer de webpagina het resultaat is van, of een stap in, een proces.",DETAILS:{}},"2.4.6":{TITLE:"Koppen en labels",DESCRIPTION:"Koppen en labels beschrijven het onderwerp of doel.",DETAILS:{}},"2.4.7":{TITLE:"Focus zichtbaar",DESCRIPTION:"Elke gebruikersinterface die met een toetsenbord te bedienen is, heeft een bedieningswijze waarbij de indicator van de toetsenbordfocus zichtbaar is.",DETAILS:{}},"2.4.8":{TITLE:"Locatie",DESCRIPTION:"Informatie over de locatie van de gebruiker binnen een verzameling webpagina's is beschikbaar.",DETAILS:{}},"2.4.9":{TITLE:"Linkdoel (alleen link)",DESCRIPTION:"Er is een mechanisme beschikbaar waarmee het doel van elke link bepaald kan worden op basis van alleen de linktekst, behalve waar het doel van de link dubbelzinnig voor gebruikers in het algemeen zou zijn.",DETAILS:{}},"2.4.10":{TITLE:"Paragraafkoppen",DESCRIPTION:"Paragraaf koppen worden gebruikt om de content te structureren.",DETAILS:{}},"2.5.1":{TITLE:"Aanwijzergebaren",DESCRIPTION:"Alle functionaliteit waarmee bij de bediening gebruik wordt gemaakt van meerpunts- of padgebaseerde gebaren, kan worden bediend met een enkele aanwijzer zonder een padgebaseerd gebaar, tenzij een meerpunts- of padgebaseerd gebaar essentieel is.",DETAILS:{}},"2.5.2":{TITLE:"Aanwijzerannulering",DESCRIPTION:"Voor functionaliteit die kan worden bediend met een enkele aanwijzer, geldt ten minste één van de volgende zaken:",DETAILS:{1:{DESCRIPTION:"Het down-event van de aanwijzer wordt niet gebruikt om enig onderdeel van de functie uit te voeren;",TITLE:"Geen down-event"},2:{DESCRIPTION:"De functie wordt voltooid door het up-event en er is een mechanisme beschikbaar om de functie af te breken voordat deze wordt voltooid of om de functie ongedaan te maken als deze is voltooid;",TITLE:"Afbreken of ongedaan maken"},3:{DESCRIPTION:"Met het up-event wordt elk resultaat van het voorgaande down-event ongedaan gemaakt;",TITLE:"Up reversal"},4:{DESCRIPTION:"Het voltooien van de functie met het down-event is essentieel.",TITLE:"Essentieel"}}},"2.5.3":{TITLE:"Label in naam",DESCRIPTION:"Bij componenten van de gebruikersinterface met labels die tekst of afbeeldingen van tekst bevatten, bevat de naam de tekst die visueel wordt weergegeven.",DETAILS:{}},"2.5.4":{TITLE:"Bewegingsactivering",DESCRIPTION:"Functionaliteit die kan worden bediend door de beweging van een apparaat of beweging van een gebruiker, kan ook worden bediend met componenten van de gebruikersinterface. De reactie op de beweging kan worden uitgeschakeld om onbedoelde activering te voorkomen, behalve wanneer:",DETAILS:{1:{DESCRIPTION:"De beweging wordt gebruikt om de functionaliteit te bedienen via een door toegankelijkheid ondersteunde interface;",TITLE:"Ondersteunde interface"},2:{DESCRIPTION:"De beweging is essentieel voor de functie en wanneer de reactie op de beweging wordt uitgeschakeld, wordt de activiteit ongeldig gemaakt.",TITLE:"Essentieel"}}},"2.5.5":{TITLE:"Grootte van het aanwijsgebied (uitgebreid)",DESCRIPTION:"De grootte van het aanwijsgebied voor aanwijzerinvoer is ten minste 44 bij 44 CSS-pixels, behalve in de volgende gevallen:",DETAILS:{1:{DESCRIPTION:"Het doel is beschikbaar via een gelijkwaardige link of een bedieningselement van ten minste 44 bij 44 CSS-pixels op dezelfde pagina;",TITLE:"Gelijkwaardig"},2:{DESCRIPTION:"Het doel bevindt zich in een regel of tekstblok;",TITLE:"Inline"},3:{DESCRIPTION:"De doelgrootte wordt bepaald door de user agent en wordt niet aangepast door de auteur.",TITLE:"User agent control"},4:{DESCRIPTION:"Een specifieke weergave van het doel is essentieel voor de informatie die wordt overgebracht.",TITLE:"Essentieel"}}},"2.5.6":{TITLE:"Input gelijktijdige invoermechanismen",DESCRIPTION:"Webcontent beperkt niet het gebruik van de invoermanieren die op een platform beschikbaar zijn, behalve wanneer de beperking essentieel is, deze vereist is om de beveiliging van de content te garanderen of deze vereist is om gebruikersinstellingen te beschermen.",DETAILS:{}},"3.1.1":{TITLE:"Taal van de pagina",DESCRIPTION:"De standaard menselijke taal van diverse webpagina's kan door software bepaald worden.",DETAILS:{}},"3.1.2":{TITLE:"Taal van onderdelen",DESCRIPTION:"De menselijke taal van elke passage of zin in de content kan door software bepaald worden, behalve waar het gaat om eigennamen, technische termen, woorden uit een onbepaalde taal en woorden of zinsdelen die deel zijn gaan uitmaken van het jargon van de onmiddellijk omringende tekst.",DETAILS:{}},"3.1.3":{TITLE:"Ongebruikelijke woorden",DESCRIPTION:"Er is een mechanisme beschikbaar voor de identificatie van specifieke definities van woorden of zinsdelen die op een ongebruikelijke of beperkte manier gebruikt worden, inclusief idiomatische uitdrukkingen en jargon.",DETAILS:{}},"3.1.4":{TITLE:"Afkortingen",DESCRIPTION:"Er is een mechanisme beschikbaar voor de identificatie van de voluit geschreven vorm of betekenis van afkortingen.",DETAILS:{}},"3.1.5":{TITLE:"Leesniveau",DESCRIPTION:"Als tekst, nadat eigennamen en titels verwijderd zijn, een leesvaardigheid vereist die hoger is dan het lager middelbaar onderwijsniveau, dan is aanvullende content beschikbaar, of er is een versie beschikbaar die geen leesvaardigheid vereist die hoger is dan het lager middelbaar onderwijsniveau.",DETAILS:{}},"3.1.6":{TITLE:"Uitspraak",DESCRIPTION:"Er is een mechanisme beschikbaar voor het vaststellen van de specifieke uitspraak van woorden indien de betekenis van de woorden in de context dubbelzinnig is zonder kennis van de uitspraak.",DETAILS:{}},"3.2.1":{TITLE:"Bij focus",DESCRIPTION:"Als een component van de gebruikersinterface de focus krijgt, dan veroorzaakt dat geen contextwijziging.",DETAILS:{}},"3.2.2":{TITLE:"Bij input",DESCRIPTION:"Verandering van de instelling van een component van de gebruikersinterface veroorzaakt niet automatisch een contextwijziging, tenzij de gebruiker geïnformeerd is over het gedrag vóór het gebruik van de component.",DETAILS:{}},"3.2.3":{TITLE:"Consistente navigatie",DESCRIPTION:"Navigatiemechanismen, die op meerdere webpagina's binnen een verzameling webpagina's herhaald worden, komen elke keer dat ze worden herhaald in dezelfde relatieve volgorde voor, tenzij een verandering wordt geïnitieerd door de gebruiker.",DETAILS:{}},"3.2.4":{TITLE:"Consistente identificatie",DESCRIPTION:"Componenten die dezelfde functionaliteit hebben binnen een verzameling webpagina's worden consistent geïdentificeerd.",DETAILS:{}},"3.2.5":{TITLE:"Verandering op verzoek",DESCRIPTION:"Contextwijzigingen worden alleen geïnitieerd op verzoek van de gebruiker of er is een mechanisme beschikbaar om zulke veranderingen uit te zetten.",DETAILS:{}},"3.3.1":{TITLE:"Foutidentificatie",DESCRIPTION:"Als een invoerfout automatisch ontdekt wordt, dan wordt het onderdeel waar de fout zit geïdentificeerd en wordt de fout tekstueel aan de gebruiker meegedeeld.",DETAILS:{}},"3.3.2":{TITLE:"Labels of instructies",DESCRIPTION:"Als de content gebruikersinvoer vereist, dan worden labels of instructies geleverd.",DETAILS:{}},"3.3.3":{TITLE:"Foutsuggestie",DESCRIPTION:"Als een invoerfout automatisch ontdekt wordt en suggesties voor verbetering bekend zijn, dan worden de suggesties aan de gebruiker geleverd, tenzij dit de beveiliging of het doel van de content in gevaar zou brengen.",DETAILS:{}},"3.3.4":{TITLE:"Foutpreventie (wettelijk, financieel, gegevens)",DESCRIPTION:"Voor webpagina's die wettelijke verplichtingen of financiële transacties voor de gebruiker uitvoeren, die, door gebruikers bedienbaar gegevens in gegevensopslagplaatsen verwijderen of wijzigen, of die antwoorden van de gebruiker verzenden, geldt ten minste één van de volgende zaken:",DETAILS:{1:{DESCRIPTION:"Verzendingen kunnen ongedaan gemaakt worden.",TITLE:"Omkeerbaar"},2:{DESCRIPTION:"Door de gebruiker ingevoerde gegevens worden gecontroleerd op invoerfouten en de gebruiker wordt de mogelijkheid gegeven om ze te verbeteren.",TITLE:"Gecontroleerd"},3:{DESCRIPTION:"Er is een mechanisme beschikbaar voor het beoordelen, bevestigen en verbeteren van informatie voordat de verzending wordt voltooid.",TITLE:"Bevestigd"}}},"3.3.5":{TITLE:"Hulp",DESCRIPTION:"Contextgevoelige hulp is beschikbaar.",DETAILS:{}},"3.3.6":{TITLE:"Foutpreventie (alle)",DESCRIPTION:"Voor webpagina's die vereisen dat de gebruiker informatie invoert en verzendt, geldt ten minste één van de volgende zaken:",DETAILS:{1:{DESCRIPTION:"Verzendingen kunnen ongedaan gemaakt worden.",TITLE:"Omkeerbaar"},2:{DESCRIPTION:"Door de gebruiker ingevoerde gegevens worden gecontroleerd op invoerfouten en de gebruiker wordt de mogelijkheid gegeven om ze te verbeteren.",TITLE:"Gecontroleerd"},3:{DESCRIPTION:"Er is een mechanisme beschikbaar voor het beoordelen, bevestigen en verbeteren van informatie voordat de verzending wordt voltooid.",TITLE:"Bevestigd"}}},"4.1.1":{TITLE:"Parsen",DESCRIPTION:"In content die geïmplementeerd is met opmaaktalen hebben elementen volledige begin- en eindtags, zijn elementen genest volgens hun specificatie, bevatten elementen geen dubbele attributen en zijn alle ID's uniek, behalve waar de specificatie deze eigenschappen toelaat.",DETAILS:{}},"4.1.2":{TITLE:"Naam, rol, waarde",DESCRIPTION:"Voor alle componenten van de gebruikersinterface (inclusief, maar niet uitsluitend voor formulierelementen, links en door scripts gegenereerde componenten), kunnen de naam (name) en rol (role) door software bepaald worden; toestanden (states), eigenschappen (properties) en waarden (values) die door de gebruiker ingesteld kunnen worden, kunnen door software ingesteld worden; en kennisgeving van veranderingen in deze items is beschikbaar voor user agents, met inbegrip van hulptechnologieën.",DETAILS:{}},"4.1.3":{TITLE:"Statusberichten",DESCRIPTION:"In content die is geïmplementeerd met opmaaktalen kunnen statusberichten door software bepaald worden met behulp van rol (role) of eigenschappen (properties), zodat hulptechnologieën de berichten aan de gebruiker kunnen presenteren zonder dat ze de focus krijgen.",DETAILS:{}},"2.4.11":{TITLE:"Focus niet bedekt (minimum)",DESCRIPTION:"Wanneer een component van de gebruikersinterface de toetsenbordfocus krijgt, wordt die component niet volledig bedekt door de content die door de auteur is gecreëerd.",DETAILS:{}},"2.4.12":{TITLE:"Focus niet bedekt (uitgebreid)",DESCRIPTION:"Wanneer een component van de gebruikersinterface de toetsenbordfocus krijgt, wordt geen enkel deel van die component bedekt door de content die door de auteur is gecreëerd.",DETAILS:{}},"2.4.13":{TITLE:"Focusweergave",DESCRIPTION:"Wanneer de toetsenbordfocusindicator zichtbaar is, voldoet een gebied van de focusindicator aan alle volgende voorwaarden:",DETAILS:{}},"2.5.7":{TITLE:"Sleepbewegingen",DESCRIPTION:"Alle functionaliteit die voor de bediening gebruik maakt van een sleepbeweging kan worden bereikt door een enkele aanwijzer zonder slepen, tenzij slepen essentieel is of de functionaliteit wordt bepaald door de user agent en niet wordt aangepast door de auteur.",DETAILS:{}},"2.5.8":{TITLE:"Grootte van het aanwijsgebied (minimum)",DESCRIPTION:"De grootte van het aanwijsgebied voor aanwijzerinvoer is ten minste 24 bij 24 CSS pixels, behalve in de volgende gevallen:",DETAILS:{}},"3.2.6":{TITLE:"Consistente hulp",DESCRIPTION:"Als een webpagina een van de volgende hulpmechanismen bevat, en die mechanismes op meerdere webpagina's binnen een verzameling webpagina's worden herhaald, dan komen ze in dezelfde relatieve volgorde voor ten opzichte van andere paginacontent, tenzij een wijziging wordt geïnitieerd door de gebruiker:",DETAILS:{}},"3.3.7":{TITLE:"Overbodige invoer",DESCRIPTION:"Informatie die eerder is ingevoerd door of aangeboden aan de gebruiker en opnieuw moet worden ingevoerd tijdens hetzelfde proces is:",DETAILS:{}},"3.3.8":{TITLE:"Toegankelijke authenticatie (minimum)",DESCRIPTION:"Een cognitieve functietest (zoals het onthouden van een wachtwoord of het oplossen van een puzzel) is bij geen enkele stap van een authenticatie proces verplicht, tenzij die stap ten minste een van de volgende opties biedt:",DETAILS:{}},"3.3.9":{TITLE:"Toegankelijke authenticatie (uitgebreid)",DESCRIPTION:"Een cognitieve functietest (zoals het onthouden van een wachtwoord of het oplossen van een puzzel) is bij geen enkele stap van een authenticatie proces verplicht, tenzij die stap ten minste een van de volgende opties biedt:",DETAILS:{}}}},n={AUDIT:{ASSERTION_RESULT_DESCRIPTION_LABEL:"Bevindingen",BTN_EXPAND_PAGES:"Invoer voor gekozen items weergeven",HD_SAMPLE_SELECT:"Voeg bevindingen toe over",HOW_TO:"Hoe te voldoen",INTRO:"Beschrijf de resultaten uit de evaluatie van de geselecteerde steekproef in de vorige stap. Vergelijk de resultaten tussen de geselecteerde steekproef en de willekeurige steekproef, en pas waar nodig de geselecteerde steekproef in de vorige stap aan.",IMPORT_DATA_INTRO:"Voeg data toe uit andere (automatische) tests",RESOURCE_LINK_NAME:"Stap 4: Toets de steekproef",LABEL_OUTCOME:"Uitkomst",NO_SAMPLE:"Geen steekproef beschikbaar.",RESULTS_FOR:"Uitkomst voor",SAMPLE_FINDINGS:"Hele steekproef",SELECT_ALL:"Alles selecteren",TITLE:"Stap 4: Toets de steekproef",UNDERSTAND:"Toelichting",VIEW_IN_REPORT:"In rapport",LABEL_VERSION:"Versie van WCAG",LABEL_LEVEL:"Conformanceniveau",ADDED_IN:"Toegevoegd in"},EXPLORE:{TITLE:"Stap 2: Verken het te onderzoeken digitale product",INTRO:"Verken het digitale product om zo het doel en de functie van het digitale product te achterhalen. Deze stap helpt u te bepalen welke varianten van de items uit de steekproef te bekijken in de volgende stappen. Achterhaal welke technologieën in het digitale product zijn gebruikt, en als u wilt, neem notities over belangrijke aspecten van het digitale product. Het is gebruikelijk om voor deze stap input van de eigenaar en ontwikkelaars van het digitale product mee te nemen.",RESOURCE_LINK_NAME:"Stap 2: Verken het te onderzoeken digitale product",HD_RELIEDUP_TECH:"Technologieën waarop gesteund wordt",INF_RELIEDUP_TECH:"Bepaal op welke technologieën het digitale product steunt [volgens WCAG 2](https://www.w3.org/TR/WCAG22/#dfn-relied-upon). Voor meer informatie, zie [WCAG-EM Stap 2.4: Identificeer technologieën waarop gesteund wordt](https://www.w3.org/TR/WCAG-EM/#step2d).",LABEL_TECH:"Technologie",LABEL_TECH_SPEC:"Specificatie adres (URL)",BTN_ADD_TECH:"Technologie toevoegen",HD_NOTE_TAKING:"Eventuele aantekeningen uit verkenning",INF_NOTE_TAKING:"In dit onderdeel kunt u aantekeningen zetten die u maakt bij het verkennen van het digitale product. Deze aantekeningen kunt u in de volgende stap gebruiken om gekozen items voor de steekproef te selecteren voor de evaluatie. **Deze notities komen niet in het eindrapport.** Wel worden ze bewaard wanneer u het onderzoek opslaat en het bestand later opent.",LABEL_ESSENT_FUNC:"Functionaliteiten essentieel voor het digitale product",INF_ESSENT_FUNC:"Gebruik dit veld om essentiële functionaliteiten van het digitale product te noteren. Voorbeelden van essentiële functionaliteiten zijn: <ul><li>Selecteer en bestel een product uit de webwinkel van de website</li><li>Afronden en versturen van enquêteformulieren</li><li>Een account registreren</li></ul> Meer informatie vindt u in [WCAG-EM Stap 2.2: Identificeer essentiële functionaliteiten van het digitale product](https://www.w3.org/TR/WCAG-EM/#step2b)",LABEL_VARIETY_PAGE_TYPES:"Diverse gekozen items",INF_VARIETY_PAGE_TYPES:"Gebruik dit veld om bij te houden welke diverse varianten van items u in het digitale product heeft gevonden. Het gaat hier bijvoorbeeld om verschillende (opmaak)stijlen, layouts, indelingen en functionaliteiten in het gekozen digitale product. Meer informatie vindt u in [WCAG-EM Stap 2.3: Identificeer diverse varianten van items](https://www.w3.org/TR/WCAG-EM/#step2c).<br> **Opmerking**: Items kunnen in verschillende varianten bestaan; zie de definitie [varianten van geselecteerde items](https://www.w3.org/TR/wcag-em/#principle-of-product-enclosure).",ADD_TECH:"Toevoegen"},REPORT:{TITLE:"Rapport",BTN_SAVE_HTML:"Download het evaluatierapport (HTML)",BTN_SAVE_JSON:"Bewaar de evaluatiedata (JSON)",HEADER_SUCCESS_CRITERION:"Succescriterium",HEADER_RESULT:"Uitkomst",HEADER_OBSERVATIONS:"Bevindingen",NO_OBSERVATIONS_FOUND:"Geen bevindingen beschreven"},SAMPLE:{TITLE:"Stap 3: Selecteer een representatieve steekproef",INTRO:"Selecteer items voor de evaluatie. U vindt hier uw aantekeningen uit de vorige stap, om u te helpen items voor de steekproef te selecteren. Zorg ervoor dat de gekozen items representatief zijn voor het te toetsen digitale product.",RESOURCE_LINK_NAME:"Stap 3: Selecteer een representatieve steekproef",HD_STRUCT_SAMPLE:"Geordende steekproef",HD_ESSENT_FUNC:"Essentiële functionaliteiten (optionele notities uit vorige stap)",HD_VARIETY_PAGE_TYPES:"Diverse items uit de steekproef (optionele notities uit vorige stap)",HD_STRUCT_SAMPLE_SUB:"Geselecteerde steekproef",INF_STRUCT_SAMPLE:"Selecteer representatieve items voor alle (1) veelgebruikte onderdelen van het digitale product, (2) essentiële functionaliteiten, (3) varianten van geselecteerde items, (4) technologieën waarop gesteund wordt, en (5) overige relevante items. Meer informatie vindt u in [WCAG-EM Stap 3.1: Gebruik een geordende sample](https://www.w3.org/TR/WCAG-EM/#step3a)</a>.<br> **Opmerking**: Items kunnen in verschillende varianten bestaan; zie de definitie [varianten van geselecteerde items](https://www.w3.org/TR/wcag-em/#principle-of-product-enclosure)",HD_RANDOM_SAMPLE:"Willekeurige steekproef",INF_RAND_SAMPLE:"Selecteer willekeurig items binnen de steekproef; gebruik 10% van de grootte van de geordende steekproef. Meer informatie vindt u in [WCAG-EM Stap 3.2: Gebruik een willekeurige steekproef](https://www.w3.org/TR/WCAG-EM/#step3b).<br> **Opmerking**: Items kunnen in verschillende varianten bestaan; zie de definitie [varianten van geselecteerde items](https://www.w3.org/TR/wcag-em/#principle-of-product-enclosure)",RAND_SAMPLE_LENGTH:"Selecteer minimaal {REQUIRED_RANDOM_SAMPLE_COUNT} willekeurige gekozen items.",LABEL_HANDLE:"korte titel",LABEL_PAGE:"Locatie (URL) of instructie",NO_PAGES_DEFINED:"Er is geen item in deze lijst",ITEM:"Item",BTN_ADD_PAGE:"Item toevoegen",BTN_REMOVE_PAGE:"Item verwijderen",SAMPLE_PAGE:"Steekproef item",DELETE_CONFIRM:"Weet u zeker dat u dit item uit de steekproef wilt verwijderen?"},SCOPE:{TITLE:"Stap 1: Bepaal de scope van de evaluatie",INTRO:"Bepaal de basiseisen en scope van de evaluatie. Dit wordt bij voorkeur gedaan door de opdrachtgever van de evaluatie (dit kan, maar hoeft niet de eigenaar van het digitale product te zijn), om ervoor te zorgen dat de verwachtingen op de opdracht aansluiten.",RESOURCE_LINK_NAME:"Stap 1: Bepaal de scope van de evaluatie",LABEL_SITE_NAME:"Naam van het digitale product",INF_SITE_NAME:"Vul een naam in van het te evalueren digitale product. Bijvoorbeeld:<ul><li>“Publiek digitaal product van Voorbeeld Organisatie”</li><li>“Webshop van Voorbeeld Bedrijf”</li><li>“Intranet van Voorbeeld Universiteit”</li></ul>",LABEL_SITE_SCOPE:"Scope van het digitale product",INF_SITE_SCOPE_0:"Leg de scope van het digitale product vast, zodat duidelijk is welke items binnen de evaluatie vallen. Voor meer informatie, zie [WCAG-EM Stap 1.1: Definieer de scope van het digitale product](https://www.w3.org/TR/WCAG-EM/#step1a). Bijvoorbeeld:",INF_SITE_SCOPE_LI0:"“Alle content van de publieke website van Voorbeeld Org. op `https://www.voorbeeld.org`”",INF_SITE_SCOPE_LI1:"“Alle content van de webwinkel van Voorbeeld Org. op `https://www.voorbeeld.org/shop/`”",INF_SITE_SCOPE_LI2:"“Alle content in de app van Voorbeeld Org. op `https://appstore.voorbeeld.org`”",LABEL_WCAG_VERSION:"WCAG Versie",INFO_WCAG_VERSION:"Selecteer de WCAG versie waarmee wordt geëvalueerd. Versie 2.2 (standaard), 2.1, or 2.0",WCAG20:"WCAG 2.0",WCAG21:"WCAG 2.1",WCAG22:"WCAG 2.2",LABEL_CONFORMANCE_TGT:"Conformiteitsdoel",INF_CONF_TGT:"Bepaal het te behalen WCAG 2 conformiteitsniveau ('A', 'AA' of 'AAA') voor de evaluatie. Voor meer informatie, zie [WCAG-EM Stap 1.2: Bepaal het conformiteitsdoel](https://www.w3.org/TR/WCAG-EM/#step1b). Deze keuze bepaalt welke niveaufilters in “Stap 4: Evalueer steekproef” standaard aan zullen staan.",LABEL_SUPPORT_BASE:"Basisniveau van toegankelijkheid-ondersteuning",INF_SUPPORT_BASE:"Bepaal welke browser, hulptechnologieën en andere [user agents](https://www.w3.org/TR/WCAG22/#useragentdef) [door toegankelijkheid ondersteund](https://www.w3.org/TR/WCAG22/#accessibility-supporteddef) zijn door het digitale product. Bijvoorbeeld: “Edge met JAWS”, “Firefox met NVDA”, en “Safari met VoiceOver” zou het basisniveau kunnen zijn. Voor meer informatie, zie [WCAG-EM Stap 1.3: Bepaal het Basisniveau van toegankelijkheid-ondersteuning](https://www.w3.org/TR/WCAG-EM/#step1c).",LABEL_EXTRA_REQUIREMENTS:"Verdere onderzoeksvereisten",INF_EXTRA_REQUIREMENTS_0:"Bepaal overige onderzoeksvereisten. Voor meer informatie, zie [WCAG-EM Stap 1.4: Bepaal verdere onderzoeksvereisten](https://www.w3.org/TR/WCAG-EM/#step1d). Bijvoorbeeld:",INF_EXTRA_REQUIREMENTS_LI0:"“In het rapport wordt een volledige lijst van de gevonden problemen opgenomen, in plaats van slechts enkele voorbeelden”",INF_EXTRA_REQUIREMENTS_LI1:"“In het rapport zal een omschrijving van de problemen gegeven worden, inclusief suggesties voor het oplossen van de problemen”",INF_EXTRA_REQUIREMENTS_LI2:"“Alle items uit de steekproef en de bijbehorende content van het digitale product zullen in de evaluatie getest worden, in plaats van uitsluitend de steekproef”",DATA_LOSS_WARNING:"Deze wijziging verwijderd één of meerdere al geëvalueerde criteria van het rapport. Uw bevindingen bij deze criteria zullen verwijdert worden. Weet u weet zeker dat u door wilt gaan?"},START:{TITLE:"WCAG-EM Report Tool",SUBTITLE:"Overzicht",INTRO_HD:"Wat de tool doet",INTRO_1:"Deze tool maakt een rapport op basis van uw bevindingen in het toegankelijkheidsonderzoek. Het is gebaseerd op de <span lang='en'>WCAG Evaluation Methodology</span> ([WCAG-EM](https://www.w3.org/TR/WCAG-EM/)).",TIPS_HD:"Tips voor het gebruik van deze tool",TIPS_1:"Onder “Bekijk Report”, kunt u uw rapport downloaden als HTML (webpagina) of als JSON (gestructureerde data).",TIPS_2:"U kunt bevindingen beschrijven in <a href='https://en.wikipedia.org/wiki/Markdown'>Markdown</a>, zodat u bijvoorbeeld lijsten, links en codevoorbeelden kunt toevoegen. Dit werkt ook op de velden “managementsamenvatting” en “onderbouwing van de evaluatie”.",TIPS_3:"Deze tool slaat de informatie die u toevoegt niet automatisch op. Om data op te slaan, gebruik de Windows sneltoets <kbd>Ctrl</kbd>+<kbd>S</kbd> of de Mac sneltoets <kbd>Cmd</kbd>+<kbd>S</kbd> om het “Save“-venster te openen.",ABOUT_HEADING:"Over deze tool",ABOUT_1:"<p>De WCAG-EM Report Tool is er om een <a href='https://www.w3.org/WAI/eval/report-tool/evaluation/view-report'>gestructureerd rapport</a> te maken van de bevindingen uit een toegankelijkheidsonderzoek.</p>",ABOUT_2:"<p>Deze tool voert geen automatische tests uit. Het is bedoeld voor ervaren toegankelijkheidsonderzoekers. Kennis wordt verondersteld van Web Content Accessibility Guidelines (<a href='https://www.w3.org/TR/WCAG22/'>WCAG</a>), toegankelijk bouwen, hulptechnologieën en over het gebruik van digitale producten door mensen met een functiebeperking (zoals beschreven in de sectie <a lang='en' href='http://www.w3.org/TR/WCAG-EM/#expertise'>Required Expertise</a> van WCAG-EM.</p>",USAGE_HD:"Hoe deze tool werkt",USAGE_LI1:"Alle functionaliteit is direct in uw webbrowser beschikbaar. U heeft geen internetverbinding nodig vanaf dit punt. <br> **Opmerking:** Wanneer u het venster van de webbrowser sluit, raken gegevens die u niet heeft bewaard verloren.",USAGE_LI2:"Alle gegevens die u invult worden als JSON data op de achtergrond bewaard (in uw webbrowser, niet op een server). U kunt periodiek opslaan terwijl u werkt, om te voorkomen dat u data verliest mocht uw webbrowser sluiten.",USAGE_LI3:"U kunt tussentijdse rapporten bewaren en er later aan verder werken. Gebruik de “Open rapport” knop op de eerste pagina en laad daar het bestand dat u eerder hebt opgeslagen.",CHOICES_HEADING:"Resultaat keuzes",CHOICES_INTRO:"Als u verder gaat om de evalueren, selecteert u een “resultaat“ voor ieder succescriterium. Hier is een legenda met de betekenis van deze keuzes:",CHOICES_DT1:"Niet beoordeeld",CHOICES_DD1:"Dit succescriterium is niet gecontroleerd.",CHOICES_DT2:"Goedgekeurd",CHOICES_DD2:"Dit succescriterium is goedgekeurd",CHOICES_DT3:"Afgekeurd",CHOICES_DD3:"Dit succescriterium is niet goedgekeurd.",CHOICES_DT4:"Niet van toepassing",CHOICES_DD4:"Dit succescriterium hangt samen met een functionaliteit die ontbreekt in deze authoring tool, dus is het niet van toepassing.",CHOICES_DT5:"Onduidelijk",CHOICES_DD5:"Het is onduidelijk of dit succescriterium is behaald.",WELCOME_MESSAGE:"<strong>Opmerking:</strong> De WCAG-EM Report Tool is gebaseerd op <a href='https://www.w3.org/WAI/test-evaluate/conformance/wcag-em/#versiondiff'>WCAG-EM 2</a>. Het kan worden gebruikt om websites, apps en andere digitale producten te evalueren. Alle wijzigingen worden bijgehouden in de <a href='https://github.com/w3c/wai-wcag-em-report-tool/releases/tag/4.1.0'>changelog</a>."},SUMMARY:{TITLE:"Stap 5: Evaluatiebevindingen rapporteren",INTRO:"Benoem verdere bevindingen uit de evaluatie die u in het rapport wilt hebben. De toetsresultaten uit de vorige stap vindt u onder “Uitgebreide toetsresultaten” ter review, en om u te helpen bij het schrijven van de samenvatting.",RESOURCE_LINK_NAME:"Stap 5: Evaluatiebevindingen rapporteren",LABEL_TITLE:"Rapporttitel",TITLE_PREFIX:"Rapportage van",INF_TITLE:"Vul hier de titel in van het evaluatierapport van de toegankelijkheid van het digitale product. Bijvoorbeeld: <ul><li>“Evaluatierapport voor Voorbeeldorganisatie”</li><li>“Webshop Toegankelijkheidsanalyse en verbetersuggesties”</li></ul>",LABEL_COMMISSIONER:"Evaluatieopdrachtgever",INF_COMMISSIONER:"De persoon, het team, de organisatie, het departement of andere entiteit die opdracht voor de evaluatie gaf.",LABEL_CREATOR:"Evaluator",INF_CREATOR:"De persoon, het team, de organisatie, het departement of andere entiteit verantwoordelijk voor het uitvoeren van de evaluatie.",LABEL_DATE:"Evaluatiedatum",INF_DATE:"Vul hier de datum in waarop de evaluatie werd afgerond, of de datums waarop de evaluatie plaats vond. U kunt elk datumformaat gebruiken. Schrijf de maand volledig uit, zodat het internationaal beter werkt. <br> **Opmerking:** Het datumformaat 01-02-2022 is ambigu: Het kan zowel 2 januari als 1 februari betekenen in diverse landen.",LABEL_SUMMARY:"Managementsamenvatting",INF_SUMMARY:"Geef een korte samenvatting van de bevindingen uit de evaluatie om zo een overzicht van de resultaten te krijgen. Benoem bijvoorbeeld de algehele toegankelijkheid van het digitale product, met enkele concrete voorbeelden uit het onderzoek, zoals de frequentie van bepaalde verbeterpunten.",LABEL_SPECIFICS:"Benoem de onderbouwing van de evaluatie (optioneel)",INF_SPECIFICS:"WCAG-EM raadt aan dat u de getoetste items uit de steekproef bewaart. Meer informatie hierover vindt u in <a href={{link_em_5b}}>WCAG-EM Stap 5.2: Benoem de onderbouwing van de evaluatie</a>. Gebruik dit tekstveld tevens om de gebruikte evaluatietools, browsers, hulptechnologieën, andere software en toetsmethodes vast te leggen. Dit zal tevens in het eindrapport staan. U kunt deze informatie na het downloaden van het rapport als HTML-bestand nog bijwerken.",HD_CRITERIA_REPORT:"Uitgebreide toetsresultaten"}},t={COMMON:{MORE_INFO:"Voor meer informatie, zie <a href={{url}}>{{name}}</a>.",HIDE_MESSAGE:"Verberg bericht",ERROR:{DEFAULT:"Er is iets misgegaan."},YES:"Ja",NO:"Nee",NEXT:"Volgende {label}",PREVIOUS:"Vorige {label}",BUTTON:{ADD:"{subject} toevoegen",INFO:"info",HIDE:"Verberg {subject}",LANGUAGE_SELECT:"vertalingen",SHOW:"Toon {subject}"},LABEL:{LANGUAGE_SELECT:"Deze pagina in het"},YOUR_REPORT:"Jouw rapport",SHOW_FULL_DESCRIPTION:"Toon volledige omschrijving",PREVIOUSNEXT:"Vorige/Volgende Stap",DELETE:"Verwijder",FOR:"voor",EXPAND_ALL:"Klap alle secties uit",COLLAPSE_ALL:"Sluit alle secties"},EARL:{PASSED:"Voldoende",FAILED:"Onvoldoende",CANT_TELL:"Onbekend",INAPPLICABLE:"Niet van toepassing",UNTESTED:"Niet getoetst",LEVEL_A:"Niveau A",LEVEL_AA:"Niveau AA",LEVEL_AAA:"Niveau AAA"},IMPORT:{IMPORT:{HEADING:"Geïmporteerd resultaat {IMPORT_DATE, date, ::yyyy/MM/dd} van {AUTHOR}",TEST_PREFIX:"Test"},ERROR:{JSONLD_SYNTAX:"Bestandstype wordt niet herkend.",NO_ASSERTIONS:"Het bestand bevat geen herkenbare criteria.",NO_COMPATIBLE_ASSERTIONS:"Geen van de criteria in dit bestand komt overeen met de geselecteerde steekproef.",FILE_ERROR:"Incorrect bestandstype of beschadigd bestand."},SUCCESSFUL:"De criteria zijn toegevoegd aan de bevindingen op deze pagina.",MORE_INFO:"Meer informatie over het importeren van EARL als JSON"},NAV:{MENU:"Menu",MENU_IMPORT:"Importeer gegevens",MENU_IMPORT_HINT:"EARL als JSON-LD",MENU_NEW:"Nieuw rapport",MENU_OPEN:"Open rapport",WZRD_START:"Overzicht",WZRD_SCOPE:"1. Bepaal scope",WZRD_EXPLORE:"2. Verken digitaal product",WZRD_SAMPLE:"3. Selecteer steekproef",WZRD_AUDIT:"4. Toets steekproef",WZRD_REPORT:"5. Rapporteer resultaat",WZRD_VIEWREPORT:"Bekijk rapport",STEP:"stap",STEP_START:"Start",STEP_SCOPE:"Bepaal scope",STEP_EXPLORE:"Verken digitaal product",STEP_SAMPLE:"Selecteer steekproef",STEP_AUDIT:"Toets steekproef",STEP_REPORT:"Rapporteer resultaat",STEP_VIEWREPORT:"Bekijk rapport",VIEWREPORT:"Bekijk rapport",NOT_STARTED:"Nog niet aan een rapport begonnen.",CLEARREPORT:"Opnieuw",CLEARWARNING:"Dit zal alles wat nu is ingevoerd verwijderen en een nieuw rapport starten. Weet u het zeker?"},REPORT:{BY:"Rapport auteur",COMMISION_BY:"Evaluatie opdrachtgever",HD_ABOUT:"Over deze evaluatie",HD_SUMMARY:"Managementsamenvatting",HD_SCOPE:"Scope van de evaluatie",LABEL_SITE_NAME:"Naam van het digitaal product",LABEL_SITE_SCOPE:"Scope van het digitale product",LABEL_CONFORMANCE_TGT:"Conformiteitsdoel",LABEL_EXTRA_REQUIREMENTS:"Verdere evaluatievereisten",LABEL_SUPPORT_BASE:"Basisniveau van toegankelijkheid ondersteund",LABEL_RELIEDUP_TECH:"technologieën waarop gesteund wordt",LABEL_NOT_PROVIDED:"Niet ingevuld",HD_SCORE:"Overzicht toetsresultaten",PRINCIPLE:"Principe",TOTAL_SCORE:"Totaal",HD_CRITERIA_REPORT:"Uitgebreide toetsresultaten",LABEL_DESCR:"Bevindingen",HD_SAMPLE:"Steekproef met getoetste items",HD_SPECIFICS:"Onderbouwing van de evaluatie",HD_DOCS:"Gerelateerde WCAG 2 bronnen",REPORT_FOR:"Rapport over",REPORTED_ON:"Gerapporteerd over",REPORTED_ON_OF:"van",SAVE:"Opslaan",EDIT:"Wijzig",SUMMARY:"Samenvatting",ALL_RESULTS:"Alle resultaten"}},i={WCAG:e,PAGES:n,UI:t};export{n as PAGES,t as UI,e as WCAG,i as default};
